// The ROM's data as files a person can read or view, in the data directory:
// tiles as indexed PNG files (gfx/), their maps as text (maps/), palettes as
// PNG swatches (palettes/), text (text/, files/*.INI), sound samples as WAV
// files (sfx/), everything else as .bin files (bin/, files/, anims/). The
// pieces (data_pieces.inc, generated by tools/data_pieces.py) say which ROM
// bytes go to which file. LCW packed data is stored unpacked; Decompress
// takes it from unpacked().
#include "assets.hpp"

#include "md/mem.hpp"

#include <SDL3/SDL.h>

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <map>
#include <sstream>
#include <vector>

namespace assets {
namespace {

constexpr uint32_t kRomSize = 0x100000;
constexpr uint32_t kRomCrc = 0x4DEA40BA; // Dune - The Battle for Arrakis (USA)

enum Type : uint8_t {
    kBin,    // the bytes
    kText,   // a line per NUL-ended string; '{' and other bytes than ASCII as {XX}
    kTextLf, // as kText with lines ending in LF (NUL is {00})
    kIni,    // one string, NULs after it: the text as it is
    kPng,    // 8x8 tiles of 4-bit pixels as colour indices 16 * line + pixel
    kMap,    // words (plane map cells) in hex, cols a line
    kPal,    // colours as 8x8 squares, 16 a row
    kWav,    // 8-bit unsigned PCM
};

// kPng: the line (palette line of the tiles no map shows), tiles a row (in
// bands rows tiles high, down the columns, when rows), the ROM palettes of
// lines 0-3 (0 grey) and the maps whose cells give a tile its line. kMap:
// cols. kWav: the sample rate.
struct File {
    const char* name;
    Type type;
    uint8_t line = 0, cols = 16, rows = 0;
    uint32_t pal[4] = {};
    uint32_t maps[5] = {};
    uint32_t rate = 0;
};

// The data ranges of the ROM in address order; unpacked > 0: LCW packed.
struct Piece {
    uint32_t addr, size, unpacked;
    const char* file;
};

#include "data_pieces.inc"

std::map<uint32_t, std::vector<uint8_t>> unpacked_data;

uint32_t crc32(const std::vector<uint8_t>& d) {
    uint32_t c = 0xFFFFFFFF;
    for (uint8_t b : d) {
        c ^= b;
        for (int i = 0; i < 8; i++) c = (c >> 1) ^ (0xEDB88320 & (0u - (c & 1)));
    }
    return ~c;
}

const File& file_of(const std::string& name) {
    static const File bin{nullptr, kBin};
    for (const File& f : kFiles)
        if (name == f.name) return f;
    return bin;
}

uint16_t be16(const uint8_t* p) { return uint16_t(p[0] << 8 | p[1]); }

// The game's LCW (Decompress 0xC32) into a buffer.
std::vector<uint8_t> lcw(const uint8_t* src) {
    std::vector<uint8_t> out;
    for (;;) {
        uint8_t c = *src++;
        if (!(c & 0x80)) {
            size_t from = out.size() - ((c & 0xF) << 8 | *src++);
            for (int n = (c >> 4) + 3; n; n--) out.push_back(out[from++]);
        } else if (!(c & 0x40)) {
            if (c == 0x80) return out;
            out.insert(out.end(), src, src + (c & 0x3F));
            src += c & 0x3F;
        } else if (c == 0xFE) {
            out.insert(out.end(), size_t(src[0] | src[1] << 8), src[2]);
            src += 3;
        } else {
            size_t n = c == 0xFF ? src[0] | src[1] << 8 : (c & 0x3F) + 3;
            size_t from = c == 0xFF ? src[2] | src[3] << 8 : src[0] | src[1] << 8;
            src += c == 0xFF ? 4 : 2;
            for (; n; n--) out.push_back(out[from++]);
        }
    }
}

// Colour levels of the console's 3-bit channels.
constexpr uint8_t kLevel[8] = {0, 52, 87, 116, 144, 172, 206, 255};

SDL_Color colour(uint16_t v) { return {kLevel[(v >> 1) & 7], kLevel[(v >> 5) & 7], kLevel[(v >> 9) & 7], 255}; }

uint16_t md_colour(uint8_t r, uint8_t g, uint8_t b) {
    auto level = [](uint8_t c) {
        int best = 0;
        for (int i = 1; i < 8; i++)
            if (std::abs(kLevel[i] - c) < std::abs(kLevel[best] - c)) best = i;
        return best;
    };
    return uint16_t(level(r) << 1 | level(g) << 5 | level(b) << 9);
}

// Pixel position of tile t in a kPng file.
void place(const File& f, size_t t, int* x, int* y) {
    if (f.rows) {
        size_t band = f.rows * f.cols, i = t % band;
        *x = int(i / f.rows) * 8;
        *y = int(t / band * f.rows + i % f.rows) * 8;
    } else {
        *x = int(t % f.cols) * 8;
        *y = int(t / f.cols) * 8;
    }
}

std::string text_of(const uint8_t* p, size_t n, bool lf) {
    std::string s;
    for (size_t i = 0; i < n; i++) {
        if (p[i] == (lf ? 0x0A : 0)) s += '\n';
        else if (p[i] >= 0x20 && p[i] < 0x7F && p[i] != '{') s += char(p[i]);
        else {
            char hex[8];
            std::snprintf(hex, sizeof hex, "{%02X}", p[i]);
            s += hex;
        }
    }
    return s;
}

bool bytes_of(const std::string& s, bool lf, std::vector<uint8_t>* out) {
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '\n') out->push_back(lf ? 0x0A : 0);
        else if (s[i] != '{') out->push_back(uint8_t(s[i]));
        else {
            char* end = nullptr;
            unsigned long v = std::strtoul(s.substr(i + 1, 2).c_str(), &end, 16);
            if (i + 3 >= s.size() || s[i + 3] != '}' || *end) return false;
            out->push_back(uint8_t(v));
            i += 3;
        }
    }
    return true;
}

bool write_file(const std::string& path, const void* d, size_t n) {
    std::error_code ec;
    std::filesystem::create_directories(std::filesystem::path(path).parent_path(), ec);
    std::ofstream o(path, std::ios::binary);
    o.write(static_cast<const char*>(d), std::streamsize(n));
    return bool(o);
}

bool read_file(const std::string& path, std::vector<uint8_t>* d) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return false;
    d->assign(std::istreambuf_iterator<char>(f), {});
    return true;
}

// The file's contents from the bytes of its pieces (packed ones unpacked);
// maps: the unpacked maps by ROM address, for the tiles' lines.
bool save(const std::string& path, const File& f, const std::vector<uint8_t>& d, const std::vector<uint8_t>& rom,
          const std::map<uint32_t, std::vector<uint8_t>>& maps) {
    switch (f.type) {
    case kBin:
        return write_file(path, d.data(), d.size());
    case kText:
    case kTextLf: {
        std::string s = text_of(d.data(), d.size(), f.type == kTextLf);
        return write_file(path, s.data(), s.size());
    }
    case kIni:
        return write_file(path, d.data(), std::strlen(reinterpret_cast<const char*>(d.data())));
    case kMap: {
        std::string s;
        for (size_t i = 0; i + 1 < d.size(); i += 2) {
            char w[8];
            std::snprintf(w, sizeof w, "%04X%c", be16(&d[i]), (i / 2 + 1) % f.cols ? ' ' : '\n');
            s += w;
        }
        return write_file(path, s.data(), s.size());
    }
    case kWav: {
        std::vector<uint8_t> w;
        auto put = [&](uint32_t v, int n) {
            for (int i = 0; i < n; i++) w.push_back(uint8_t(v >> (8 * i)));
        };
        w.insert(w.end(), {'R', 'I', 'F', 'F'});
        put(uint32_t(36 + d.size()), 4);
        w.insert(w.end(), {'W', 'A', 'V', 'E', 'f', 'm', 't', ' '});
        put(16, 4);
        put(1, 2); // PCM
        put(1, 2); // mono
        put(f.rate, 4);
        put(f.rate, 4);
        put(1, 2);
        put(8, 2);
        w.insert(w.end(), {'d', 'a', 't', 'a'});
        put(uint32_t(d.size()), 4);
        w.insert(w.end(), d.begin(), d.end());
        return write_file(path, w.data(), w.size());
    }
    case kPal: {
        int n = int(d.size() / 2);
        SDL_Surface* s = SDL_CreateSurface(16 * 8, (n + 15) / 16 * 8, SDL_PIXELFORMAT_RGB24);
        if (!s) return false;
        for (int i = 0; i < n; i++) {
            SDL_Color c = colour(be16(&d[i * 2]));
            SDL_Rect r{i % 16 * 8, i / 16 * 8, 8, 8};
            SDL_FillSurfaceRect(s, &r, SDL_MapSurfaceRGB(s, c.r, c.g, c.b));
        }
        std::error_code ec;
        std::filesystem::create_directories(std::filesystem::path(path).parent_path(), ec);
        bool ok = SDL_SavePNG(s, path.c_str());
        SDL_DestroySurface(s);
        return ok;
    }
    case kPng: {
        size_t n = d.size() / 32;
        int w = 0, h = 0;
        for (size_t t = 0; t < n; t++) {
            int x, y;
            place(f, t, &x, &y);
            w = std::max(w, x + 8);
            h = std::max(h, y + 8);
        }
        SDL_Surface* s = SDL_CreateSurface(std::max(w, 8), std::max(h, 8), SDL_PIXELFORMAT_INDEX8);
        if (!s) return false;
        SDL_Color c[256] = {};
        for (int i = 0; i < 64; i++)
            c[i] = f.pal[i / 16] ? colour(be16(&rom[f.pal[i / 16] + i % 16 * 2])) : colour(uint16_t(i % 16 / 2 * 0x222));
        for (int i = 64; i < 255; i++) c[i].a = 255;
        c[255] = {255, 0, 255, 255};
        SDL_SetPaletteColors(SDL_CreateSurfacePalette(s), c, 0, 256);
        std::vector<uint8_t> line(n, f.line);
        std::vector<bool> seen(n);
        for (uint32_t m : f.maps)
            if (m)
                for (size_t i = 0; i + 1 < maps.at(m).size(); i += 2) {
                    uint16_t v = be16(&maps.at(m)[i]);
                    size_t t = v & 0x7FF;
                    if (t < n && !seen[t]) {
                        line[t] = uint8_t(v >> 13 & 3);
                        seen[t] = true;
                    }
                }
        auto* px = static_cast<uint8_t*>(s->pixels);
        for (int y = 0; y < s->h; y++) std::memset(px + y * s->pitch, 255, size_t(s->w));
        for (size_t t = 0; t < n; t++) {
            int tx, ty;
            place(f, t, &tx, &ty);
            for (int y = 0; y < 8; y++)
                for (int x = 0; x < 8; x++)
                    px[(ty + y) * s->pitch + tx + x] = uint8_t(line[t] * 16 + (d[t * 32 + y * 4 + x / 2] >> (x & 1 ? 0 : 4) & 0xF));
        }
        std::error_code ec;
        std::filesystem::create_directories(std::filesystem::path(path).parent_path(), ec);
        bool ok = SDL_SavePNG(s, path.c_str());
        SDL_DestroySurface(s);
        return ok;
    }
    }
    return false;
}

// The bytes of a file (n of them, as its pieces need); false with a reason.
bool read(const std::string& path, const File& f, size_t n, std::vector<uint8_t>* d, std::string* why) {
    d->clear();
    switch (f.type) {
    case kBin:
        if (!read_file(path, d)) return false;
        *why = "not " + std::to_string(n) + " bytes";
        return d->size() == n;
    case kText:
    case kTextLf: {
        std::vector<uint8_t> s;
        if (!read_file(path, &s)) return false;
        *why = "a { not followed by two hex digits and }";
        if (!bytes_of(std::string(s.begin(), s.end()), f.type == kTextLf, d)) return false;
        *why = "not " + std::to_string(n) + " bytes of text (the strings must keep their lengths)";
        return d->size() == n;
    }
    case kIni:
        if (!read_file(path, d)) return false;
        *why = "longer than " + std::to_string(n - 1) + " bytes, or a NUL in it";
        if (d->size() >= n || std::memchr(d->data(), 0, d->size())) return false;
        d->resize(n, 0);
        return true;
    case kMap: {
        std::vector<uint8_t> s;
        if (!read_file(path, &s)) return false;
        std::istringstream in(std::string(s.begin(), s.end()));
        for (std::string w; in >> w;) {
            char* end = nullptr;
            unsigned long v = std::strtoul(w.c_str(), &end, 16);
            *why = "\"" + w + "\" is not a hex word";
            if (*end || v > 0xFFFF) return false;
            d->push_back(uint8_t(v >> 8));
            d->push_back(uint8_t(v));
        }
        *why = "not " + std::to_string(n / 2) + " words";
        return d->size() == n;
    }
    case kWav: {
        SDL_AudioSpec spec;
        Uint8* buf = nullptr;
        Uint32 len = 0;
        if (!SDL_LoadWAV(path.c_str(), &spec, &buf, &len)) return false;
        d->assign(buf, buf + len);
        SDL_free(buf);
        *why = "not 8-bit unsigned mono with " + std::to_string(n) + " samples";
        return spec.format == SDL_AUDIO_U8 && spec.channels == 1 && len == n;
    }
    case kPal:
    case kPng: {
        SDL_Surface* s = SDL_LoadPNG(path.c_str());
        if (!s) return false;
        if (f.type == kPal) {
            *why = "not " + std::to_string(n / 2) + " colours";
            bool ok = s->w == 16 * 8 && s->h == int((n / 2 + 15) / 16 * 8);
            for (size_t i = 0; ok && i < n / 2; i++) {
                Uint8 r, g, b;
                SDL_ReadSurfacePixel(s, int(i % 16 * 8 + 4), int(i / 16 * 8 + 4), &r, &g, &b, nullptr);
                uint16_t v = md_colour(r, g, b);
                d->push_back(uint8_t(v >> 8));
                d->push_back(uint8_t(v));
            }
            SDL_DestroySurface(s);
            return ok;
        }
        *why = "not an indexed PNG holding " + std::to_string(n / 32) + " tiles";
        bool ok = s->format == SDL_PIXELFORMAT_INDEX8;
        const auto* px = static_cast<const uint8_t*>(s->pixels);
        for (size_t t = 0; ok && t < n / 32; t++) {
            int tx, ty;
            place(f, t, &tx, &ty);
            ok = tx + 8 <= s->w && ty + 8 <= s->h;
            uint8_t tile[32] = {};
            for (int y = 0; ok && y < 8; y++)
                for (int x = 0; x < 8; x++)
                    tile[y * 4 + x / 2] |= uint8_t((px[(ty + y) * s->pitch + tx + x] & 0xF) << (x & 1 ? 0 : 4));
            d->insert(d->end(), tile, tile + 32);
        }
        SDL_DestroySurface(s);
        return ok;
    }
    }
    return false;
}

// Bytes the pieces of each file need, in address order.
std::map<std::string, size_t> file_sizes() {
    std::map<std::string, size_t> n;
    for (const Piece& p : kPieces) n[p.file] += p.unpacked ? p.unpacked : p.size;
    return n;
}

} // namespace

bool extract(const std::string& rom_path, const std::string& dir, std::string* err) {
    std::ifstream f(rom_path, std::ios::binary);
    if (!f) {
        *err = "Cannot read " + rom_path + ".";
        return false;
    }
    std::vector<uint8_t> rom((std::istreambuf_iterator<char>(f)), {});
    if (rom.size() != kRomSize || crc32(rom) != kRomCrc) {
        *err = rom_path + " is not a dump of Dune - The Battle for Arrakis (USA).";
        return false;
    }
    std::map<std::string, std::vector<uint8_t>> contents;
    std::map<uint32_t, std::vector<uint8_t>> maps;
    for (const Piece& p : kPieces) {
        std::vector<uint8_t>& d = contents[p.file];
        if (p.unpacked) {
            std::vector<uint8_t> u = lcw(rom.data() + p.addr);
            d.insert(d.end(), u.begin(), u.end());
            if (file_of(p.file).type == kMap) maps[p.addr] = u;
        } else {
            d.insert(d.end(), rom.begin() + p.addr, rom.begin() + p.addr + p.size);
        }
    }
    for (const auto& [name, d] : contents) {
        if (!save(dir + name, file_of(name), d, rom, maps)) {
            *err = "Cannot write " + dir + name + ".";
            return false;
        }
    }
    return true;
}

bool load(const std::string& dir, std::string* err) {
    md::rom.assign(kRomSize, 0);
    unpacked_data.clear();
    std::map<std::string, std::vector<uint8_t>> contents;
    for (const auto& [name, n] : file_sizes()) {
        std::string why;
        if (!read(dir + name, file_of(name), n, &contents[name], &why)) {
            *err = why.empty() ? "Missing or unreadable " + dir + name + "." : dir + name + ": " + why + ".";
            return false;
        }
    }
    std::map<std::string, size_t> at;
    for (const Piece& p : kPieces) {
        const uint8_t* d = contents[p.file].data() + at[p.file];
        if (p.unpacked) unpacked_data[p.addr].assign(d, d + p.unpacked);
        else std::memcpy(md::rom.data() + p.addr, d, p.size);
        at[p.file] += p.unpacked ? p.unpacked : p.size;
    }
    return true;
}

const std::vector<uint8_t>* unpacked(uint32_t src) {
    auto it = unpacked_data.find(src);
    return it == unpacked_data.end() ? nullptr : &it->second;
}

} // namespace assets
